def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_def = my.count('D')
    opp_def = op.count('D')
    last_my, last_opp = history[-1]

    if opp_def == 0:
        if my_def == 0:
            if n == 25:
                return 'D'
            return 'C'
        else:
            if my_def == 1 and last_my == 'D' and last_opp == 'C':
                return 'C'
            return 'D'

    recent_op = op[-10:]
    recent_def = sum(1 for a in recent_op if a == 'D')

    if last_opp == 'D':
        recent_my_def = (last_my == 'D') or (len(my) >= 2 and my[-2] == 'D')
        if opp_def <= n // 4 and my_def > 0 and recent_my_def and recent_def <= 2:
            return 'C'
        if recent_def >= 4 or opp_def > n * 2 // 3:
            return 'D'
        return 'D'
    else:
        if recent_def >= 3:
            return 'D'
        if last_my == 'D' and opp_def <= n // 10 and n < 90:
            return 'D'
        return 'C'
